arguments.content:
/* Orchard — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --color-primary: #1d1d1f;
  --color-secondary: #6e6e73;
  --color-light-bg: #f5f5f7;
  --color-white: #ffffff;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --color-badge: #bf4800;
  --color-green: #008a00;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  color: var(--color-primary);
  background: var(--color-white);
  line-height: 1.5;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color 0.15s;
}
a:hover { color: var(--color-link-hover); }

/* Top Nav */
.top-nav {
  background: rgba(29,29,31,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  position: sticky;
  top: 0;
  z-index: 100;
}
.top-nav-inner {
  max-width: 1024px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 22px;
  height: 48px;
}
.top-nav a {
  color: rgba(255,255,255,0.8);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.01em;
  transition: color 0.15s;
}
.top-nav a:hover { color: #fff; }
.top-nav .nav-logo {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
}
.top-nav .nav-links {
  display: flex;
  gap: 24px;
  align-items: center;
}
.nav-hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 18px;
  cursor: pointer;
}

/* Mobile Nav Drawer */
.mobile-nav {
  display: none;
  position: fixed;
  top: 48px;
  left: 0; right: 0; bottom: 0;
  background: rgba(29,29,31,0.98);
  backdrop-filter: blur(20px);
  z-index: 99;
  padding: 20px 30px;
  flex-direction: column;
  gap: 0;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  color: #f5f5f7;
  font-size: 17px;
  font-weight: 600;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

/* Ribbon Banner */
.ribbon-banner {
  background: var(--color-light-bg);
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  color: var(--color-primary);
  line-height: 1.5;
}
.ribbon-banner a {
  color: var(--color-link);
  font-weight: 500;
  white-space: nowrap;
}

/* Carousel */
.carousel-section {
  padding: 60px 0 40px;
  overflow: hidden;
}
.carousel-section .section-heading {
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 22px 20px;
}
.carousel-section .section-heading h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--color-primary);
}
.carousel-section .section-heading p {
  font-size: 21px;
  font-weight: 400;
  color: var(--color-secondary);
  margin-top: 6px;
}
.carousel-wrapper {
  position: relative;
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 22px;
}
.carousel-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -ms-overflow-style: none;
  scrollbar-width: none;
  padding-bottom: 8px;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--color-card-bg);
  border-radius: 20px;
  overflow: hidden;
  transition: transform 0.2s;
  border: 1px solid rgba(0,0,0,0.04);
}
.carousel-card:hover { transform: scale(1.02); }

.carousel-card .card-img {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  position: relative;
}
.carousel-card .card-body {
  padding: 16px 20px 20px;
}
.carousel-card .card-badge {
  display: inline-block;
  background: var(--color-badge);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  margin-bottom: 8px;
  letter-spacing: 0.03em;
}
.carousel-card .card-title {
  font-size: 17px;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 4px;
}
.carousel-card .card-tagline {
  font-size: 14px;
  color: var(--color-secondary);
  margin-bottom: 10px;
  line-height: 1.4;
}
.carousel-card .card-price {
  font-size: 14px;
  color: var(--color-primary);
  font-weight: 500;
}
.carousel-card .card-monthly {
  font-size: 12px;
  color: var(--color-secondary);
  margin-top: 2px;
}
.carousel-card .card-links {
  display: flex;
  gap: 16px;
  margin-top: 10px;
  font-size: 13px;
}

/* Carousel Arrows */
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  border: 1px solid rgba(0,0,0,0.1);
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  transition: background 0.15s, transform 0.15s;
  font-size: 16px;
  color: var(--color-primary);
}
.carousel-arrow:hover {
  background: #fff;
  transform: translateY(-70%) scale(1.08);
}
.carousel-arrow.left { left: 4px; }
.carousel-arrow.right { right: 4px; }
.carousel-arrow:disabled {
  opacity: 0.3;
  cursor: default;
}

/* Product Grid (Homepage) */
.product-grid {
  max-width: 1024px;
  margin: 0 auto;
  padding: 20px 22px 60px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.product-tile {
  border-radius: 20px;
  overflow: hidden;
  text-align: center;
  padding: 40px 24px 30px;
  min-height: 420px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  position: relative;
  transition: transform 0.2s;
}
.product-tile:hover { transform: scale(1.01); }
.product-tile h3 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 6px;
}
.product-tile .tile-tagline {
  font-size: 17px;
  color: var(--color-secondary);
  margin-bottom: 20px;
  font-weight: 400;
}
.product-tile .tile-links {
  display: flex;
  gap: 20px;
  font-size: 15px;
  margin-bottom: 20px;
}
.product-tile .tile-image {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 100px;
  min-height: 180px;
}

/* Hero Section */
.hero-section {
  text-align: center;
  padding: 80px 22px 60px;
  background: var(--color-white);
}
.hero-section h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  color: var(--color-primary);
}
.hero-section .hero-sub {
  font-size: 24px;
  color: var(--color-secondary);
  margin-top: 10px;
  font-weight: 400;
}
.hero-section .hero-ctas {
  display: flex;
  gap: 24px;
  justify-content: center;
  margin-top: 24px;
  font-size: 17px;
}

/* Entertainment Tabs */
.entertainment-section {
  max-width: 1024px;
  margin: 0 auto;
  padding: 60px 22px;
}
.entertainment-section h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
  text-align: center;
}
.ent-tabs {
  display: flex;
  justify-content: center;
  gap: 32px;
  margin-bottom: 30px;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 0;
}
.ent-tab {
  background: none;
  border: none;
  font-size: 15px;
  font-weight: 500;
  color: var(--color-secondary);
  padding: 10px 4px 14px;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.15s;
  font-family: var(--font-family);
}
.ent-tab.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}
.ent-tab:hover { color: var(--color-primary); }

.ent-content { display: none; }
.ent-content.active { display: block; }

.ent-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.ent-card {
  border-radius: 16px;
  overflow: hidden;
  background: var(--color-light-bg);
  transition: transform 0.2s;
}
.ent-card:hover { transform: scale(1.03); }
.ent-card .ent-card-img {
  width: 100%;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.ent-card .ent-card-body {
  padding: 14px 16px 18px;
}
.ent-card .ent-card-body h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 4px;
}
.ent-card .ent-card-body p {
  font-size: 12px;
  color: var(--color-secondary);
  margin-bottom: 8px;
}

/* Product Icon Bar */
.icon-bar {
  max-width: 1024px;
  margin: 0 auto;
  padding: 20px 22px 10px;
  display: flex;
  justify-content: center;
  gap: 28px;
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  min-width: 70px;
  transition: transform 0.15s;
}
.icon-bar-item:hover { transform: scale(1.05); }
.icon-bar-item .icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-light-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}
.icon-bar-item span {
  font-size: 11px;
  color: var(--color-primary);
  font-weight: 500;
  text-align: center;
}

/* Help Cards */
.help-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}
.help-card {
  background: var(--color-card-bg);
  border-radius: 20px;
  padding: 28px 24px;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform 0.2s;
}
.help-card:hover { transform: scale(1.02); }
.help-card .help-icon {
  font-size: 36px;
  margin-bottom: 12px;
}
.help-card h4 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.help-card p {
  font-size: 14px;
  color: var(--color-secondary);
  line-height: 1.5;
}

/* Difference Cards (carousel on store, grid on category pages) */
.diff-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}
.diff-card {
  background: var(--color-card-bg);
  border-radius: 20px;
  padding: 28px 24px;
  text-align: center;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform 0.2s;
}
.diff-card:hover { transform: scale(1.02); }
.diff-card .diff-icon {
  font-size: 36px;
  margin-bottom: 12px;
}
.diff-card h4 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}
.diff-card p {
  font-size: 14px;
  color: var(--color-secondary);
  line-height: 1.5;
}

/* Category Hero */
.category-hero {
  text-align: center;
  padding: 60px 22px 40px;
  background: var(--color-white);
}
.category-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.1;
  color: var(--color-primary);
}
.category-hero .category-sub {
  font-size: 21px;
  color: var(--color-secondary);
  margin-top: 8px;
}

/* Sticky Section Nav */
.section-nav {
  position: sticky;
  top: 48px;
  z-index: 50;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}
.section-nav-inner {
  max-width: 1024px;
  margin: 0 auto;
  display: flex;
  gap: 32px;
  padding: 12px 22px;
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav a {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-secondary);
  white-space: nowrap;
  padding: 4px 0;
  border-bottom: 2px solid transparent;
  transition: all 0.15s;
}
.section-nav a:hover,
.section-nav a.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

/* Category Section */
.category-section {
  padding: 60px 0 40px;
  max-width: 1024px;
  margin: 0 auto;
}
.category-section .section-inner {
  padding: 0 22px;
}
.category-section h2 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.category-section .section-sub {
  font-size: 17px;
  color: var(--color-secondary);
  margin-bottom: 24px;
}

/* Shopping Guide Cards */
.guide-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}
.guide-card {
  background: var(--color-card-bg);
  border-radius: 20px;
  padding: 28px 24px;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform 0.2s;
}
.guide-card:hover { transform: scale(1.02); }
.guide-card .guide-icon {
  font-size: 32px;
  margin-bottom: 10px;
}
.guide-card h4 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
}
.guide-card p {
  font-size: 14px;
  color: var(--color-secondary);
  line-height: 1.4;
}

/* Savings Cards */
.savings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}
.savings-card {
  background: var(--color-card-bg);
  border-radius: 20px;
  padding: 28px 24px;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform 0.2s;
}
.savings-card:hover { transform: scale(1.02); }
.savings-card .savings-icon {
  font-size: 32px;
  margin-bottom: 10px;
}
.savings-card h4 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
}
.savings-card p {
  font-size: 14px;
  color: var(--color-secondary);
  line-height: 1.4;
}

/* Brand Collab */
.brand-collab {
  max-width: 1024px;
  margin: 0 auto;
  padding: 60px 22px;
  text-align: center;
}
.brand-collab h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.brand-collab .collab-sub {
  font-size: 21px;
  color: var(--color-secondary);
  margin-bottom: 24px;
}
.brand-collab .collab-items {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
.brand-collab .collab-item {
  background: var(--color-card-bg);
  border-radius: 16px;
  padding: 20px;
  min-width: 180px;
  text-align: center;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform 0.2s;
}
.brand-collab .collab-item:hover { transform: scale(1.03); }
.brand-collab .collab-item .item-icon { font-size: 40px; margin-bottom: 8px; }
.brand-collab .collab-item h4 { font-size: 14px; font-weight: 600; }
.brand-collab .collab-item p { font-size: 12px; color: var(--color-secondary); }

/* Experience Section */
.experience-section {
  max-width: 1024px;
  margin: 0 auto;
  padding: 40px 22px 60px;
}
.experience-section h2 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}
.experience-section p {
  font-size: 15px;
  color: var(--color-secondary);
  line-height: 1.6;
  max-width: 680px;
}
.experience-section .promo {
  margin-top: 16px;
  font-size: 14px;
  color: var(--color-primary);
  font-weight: 500;
}

/* Quick Links */
.quick-links {
  max-width: 1024px;
  margin: 0 auto;
  padding: 40px 22px 60px;
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}
.quick-link-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border: 1px solid var(--color-border);
  border-radius: 980px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-primary);
  background: var(--color-white);
  cursor: pointer;
  transition: all 0.15s;
  text-decoration: none;
  font-family: var(--font-family);
}
.quick-link-btn:hover {
  background: var(--color-light-bg);
  color: var(--color-link);
}

/* Setup Support */
.setup-support {
  max-width: 1024px;
  margin: 0 auto;
  padding: 60px 22px;
  text-align: center;
  background: var(--color-light-bg);
  border-radius: 20px;
  margin: 40px 22px;
}
.setup-support h2 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.setup-support p {
  font-size: 17px;
  color: var(--color-secondary);
  margin-bottom: 20px;
}

/* Product Experience */
.product-experience {
  max-width: 1024px;
  margin: 0 auto;
  padding: 60px 22px;
  text-align: center;
}
.product-experience h2 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.product-experience p {
  font-size: 17px;
  color: var(--color-secondary);
  margin-bottom: 16px;
}

/* Special Stores */
.special-stores {
  max-width: 1024px;
  margin: 0 auto;
  padding: 60px 22px;
}
.special-stores h2 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
}
.special-stores .stores-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}
.special-stores .store-card {
  background: var(--color-card-bg);
  border-radius: 16px;
  padding: 24px 20px;
  text-align: center;
  border: 1px solid rgba(0,0,0,0.04);
  transition: transform 0.2s;
}
.special-stores .store-card:hover { transform: scale(1.02); }
.special-stores .store-card .store-icon { font-size: 32px; margin-bottom: 10px; }
.special-stores .store-card h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.special-stores .store-card p { font-size: 13px; color: var(--color-secondary); }

/* Footer */
.site-footer {
  background: var(--color-light-bg);
  padding: 20px 22px 30px;
  border-top: 1px solid var(--color-border);
}
.footer-inner {
  max-width: 1024px;
  margin: 0 auto;
}
.footer-legal {
  font-size: 12px;
  color: var(--color-secondary);
  line-height: 1.6;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 20px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 20px;
}
.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 10px;
  letter-spacing: 0.01em;
}
.footer-col ul {
  list-style: none;
}
.footer-col ul li {
  margin-bottom: 6px;
}
.footer-col ul li a {
  font-size: 12px;
  color: var(--color-secondary);
  transition: color 0.15s;
}
.footer-col ul li a:hover {
  color: var(--color-primary);
}
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--color-secondary);
  flex-wrap: wrap;
  gap: 8px;
}
.footer-bottom .footer-links {
  display: flex;
  gap: 16px;
}
.footer-bottom .footer-links a {
  font-size: 12px;
  color: var(--color-secondary);
}

/* Gradient backgrounds for product cards/tiles */
.bg-gradient-warm { background: linear-gradient(180deg, #fef3e2 0%, #fdf6ee 100%); }
.bg-gradient-cool { background: linear-gradient(180deg, #e8f0fe 0%, #f0f4fa 100%); }
