  font-weight: 400;
  letter-spacing: 0.01em;
  transition: color 0.15s;
}
.top-nav a:hover { color: #fff; }
.top-nav .nav-logo {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
}
.top-nav .nav-links {
