  .footer-col {
    border-bottom: 1px solid var(--color-border);
    padding: 10px 0;
  }
  .footer-col h5 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0;
    padding: 6px 0;
    user-select: none;
  }
  .footer-col h5::after {
    content: '+';
    font-size: 14px;
    font-weight: 400;
    color: var(--color-secondary);
    transition: transform 0.2s;
