  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }
  .footer-col.expanded ul {
    max-height: 500px;
  }

  .setup-support { margin: 40px 16px; }
}

@media (max-width: 480px) {
  .ent-grid { grid-template-columns: 1fr; }
  .carousel-card { flex: 0 0 240px; }
  .help-grid, .diff-grid, .guide-grid, .savings-grid {
    grid-template-columns: 1fr;
  }
}

